{
  "cvars": {
    "ivs": [
      {
        "description": "Whether Reader View was activated for the trial (binary indicator: 1 = Reader View on, 0 = Reader View off). Primary independent variable.",
        "columns": [
          "reader_view"
        ]
      }
    ],
    "dv": {
      "description": "Reading speed (log-transformed). The raw 'speed' column is right-skewed; we use log(speed) as the dependent variable to stabilize variance and reduce influence of extreme values.",
      "columns": [
        "log_speed"
      ]
    },
    "controls": [
      {
        "description": "Whether the participant has dyslexia (binary). This is treated as a moderator for the effect of reader_view (tests whether reader view benefits dyslexic readers differentially). (0 = no dyslexia, 1 = dyslexia). Uses dataset column dyslexia_bin.",
        "is_moderator": true,
        "moderator_on": "reader_view",
        "columns": [
          "dyslexia_bin"
        ]
      },
      {
        "description": "Log of number of words on the page (controls for text length). Derived from 'num_words'.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "log_num_words"
        ]
      },
      {
        "description": "Flesch-Kincaid readability score of the text (controls for text difficulty).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "Flesch_Kincaid"
        ]
      },
      {
        "description": "Reader age (in years).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "age"
        ]
      },
      {
        "description": "Device used by the reader (categorical: smartphone/tablet/desktop). Included as a factor control.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "device"
        ]
      },
      {
        "description": "Whether the participant is a native English speaker (binary: 1 = native English speaker, 0 = non-native). Derived from 'english_native'.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "english_native_binary"
        ]
      },
      {
        "description": "Comprehension correctness rate on questions after reading (controls for engagement/effort).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "correct_rate"
        ]
      },
      {
        "description": "Indicator whether the trial was a retake (0/1). Keeps track of retakes as possible covariate.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "retake_trial"
        ]
      },
      {
        "description": "Participant unique identifier. Used for clustering standard errors to account for repeated measures within participants (not a covariate).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "uuid"
        ]
      },
      {
        "description": "Page identifier. Kept for potential use (not used as cluster here but preserved in the transformed dataframe).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "page_id"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    \"\"\"\n    Transform raw dataset into a dataframe suitable for modeling.\n\n    Produces the following additional/modified columns required by the model:\n      - log_speed: natural log of speed (dependent variable)\n      - log_num_words: natural log of num_words (control)\n      - english_native_binary: 1 if english_native == 'Y', else 0\n\n    Filters rows with missing or invalid values for the required columns.\n    \"\"\"\n    df = df.copy()\n\n    # Required columns for analysis\n    required_cols = [\n        'uuid', 'page_id', 'reader_view', 'speed', 'num_words', 'Flesch_Kincaid',\n        'age', 'device', 'dyslexia_bin', 'english_native', 'correct_rate', 'retake_trial'\n    ]\n\n    # Drop rows with missing values in required columns\n    df = df.dropna(subset=required_cols)\n\n    # Ensure numeric columns are numeric\n    df['speed'] = pd.to_numeric(df['speed'], errors='coerce')\n    df['num_words'] = pd.to_numeric(df['num_words'], errors='coerce')\n    df['Flesch_Kincaid'] = pd.to_numeric(df['Flesch_Kincaid'], errors='coerce')\n    df['age'] = pd.to_numeric(df['age'], errors='coerce')\n    df['reader_view'] = pd.to_numeric(df['reader_view'], errors='coerce').astype(int)\n    df['dyslexia_bin'] = pd.to_numeric(df['dyslexia_bin'], errors='coerce').astype(int)\n    df['correct_rate'] = pd.to_numeric(df['correct_rate'], errors='coerce')\n    df['retake_trial'] = pd.to_numeric(df['retake_trial'], errors='coerce').astype(int)\n\n    # Remove rows with non-positive speed (cannot log-transform) or missing after coercion\n    df = df[df['speed'] > 0]\n    df = df.dropna(subset=['speed', 'num_words', 'Flesch_Kincaid', 'age', 'device', 'english_native', 'correct_rate'])\n\n    # Log-transform dependent variable and text length\n    df['log_speed'] = np.log(df['speed'].astype(float))\n    # To stabilize the influence of extreme page lengths, use log(num_words)\n    df['log_num_words'] = np.log(df['num_words'].astype(float))\n\n    # Derive english native binary: 'Y' -> 1, else 0\n    df['english_native_binary'] = df['english_native'].apply(lambda x: 1 if str(x).strip().upper() == 'Y' else 0)\n\n    # Ensure device is categorical\n    df['device'] = df['device'].astype('category')\n\n    # Optional: remove extreme outliers in log_speed by winsorizing at 1st and 99th percentiles to reduce undue influence\n    # (keeps shape while limiting extreme points). This is conservative and can be commented out if undesired.\n    lower = df['log_speed'].quantile(0.01)\n    upper = df['log_speed'].quantile(0.99)\n    df['log_speed'] = df['log_speed'].clip(lower, upper)\n\n    # Final dropna to be safe\n    final_cols = [\n        'uuid', 'page_id', 'reader_view', 'log_speed', 'dyslexia_bin', 'log_num_words',\n        'Flesch_Kincaid', 'age', 'device', 'english_native_binary', 'correct_rate', 'retake_trial'\n    ]\n    df = df.dropna(subset=final_cols)\n\n    # Reset index for cleanliness\n    df = df.reset_index(drop=True)\n\n    return df\n",
  "m_code": "def model(df: pd.DataFrame) -> any:\n    \"\"\"\n    Fit a linear model testing whether Reader View (reader_view) affects reading speed and whether\n    this effect is different for readers with dyslexia (interaction reader_view * dyslexia_bin).\n\n    Model: log_speed ~ reader_view * dyslexia_bin + log_num_words + Flesch_Kincaid + age + C(device) + english_native_binary + correct_rate + retake_trial\n\n    Uses cluster-robust standard errors clustered by participant UUID to account for repeated measures.\n\n    Returns the fitted OLS results object.\n    \"\"\"\n    import statsmodels.formula.api as smf\n\n    # Ensure required columns exist\n    required_model_cols = [\n        'log_speed', 'reader_view', 'dyslexia_bin', 'log_num_words', 'Flesch_Kincaid',\n        'age', 'device', 'english_native_binary', 'correct_rate', 'retake_trial', 'uuid'\n    ]\n    missing = [c for c in required_model_cols if c not in df.columns]\n    if missing:\n        raise ValueError(f\"Missing columns for model: {missing}\")\n\n    formula = (\n        'log_speed ~ reader_view * dyslexia_bin + log_num_words + Flesch_Kincaid + '\n        'age + C(device) + english_native_binary + correct_rate + retake_trial'\n    )\n\n    ols_mod = smf.ols(formula=formula, data=df)\n    # Cluster robust standard errors clustered on participant UUID\n    results = ols_mod.fit(cov_type='cluster', cov_kwds={'groups': df['uuid']})\n\n    # Return the fitted results object (has .summary(), .params, .bse, etc.)\n    return results\n"
}
